  craft:[
    [t('Space Shuttle','Спейс шаттл','Space Shuttle'), t('Vakata uch marta shattlda uchgan — ikki qisqa missiya va 2009-yilgi uzoq ekspeditsiyaga borish-qaytish uchun.','Ваката трижды летал на шаттле — в двух коротких миссиях и для доставки на длительную экспедицию 2009 года и возвращения.','Wakata flew on the Shuttle three times — two short missions plus the ride to and from his 2009 long-duration expedition.'), null],
    [t('Xalqaro kosmik stansiya va «Kibo» moduli','МКС и модуль «Кибо»','International Space Station and Kibo module'), t('«Kibo» — XKSdagi eng katta laboratoriya moduli, Yaponiya tomonidan qurilgan; Vakata uni yig‘ish va ishlatishda qatnashgan.','«Кибо» — крупнейший лабораторный модуль МКС, построенный Японией; Ваката участвовал в его сборке и эксплуатации.','Kibo, built by Japan, is the largest laboratory module on the ISS; Wakata took part in assembling and operating it.'), null],
    [t('«Soyuz» va «Crew Dragon»','«Союз» и Crew Dragon','Soyuz and Crew Dragon'), t('2013-yilda rus «Soyuz»ida, 2022-yilda SpaceX kompaniyasining «Crew Dragon»ida uchgan.','В 2013 году летал на российском «Союзе», в 2022 году — на Crew Dragon компании SpaceX.','He flew on Russia’s Soyuz in 2013 and on SpaceX’s Crew Dragon in 2022.'), null]
  ],
