    [t('Xalqaro kosmik stansiya','Международная космическая станция','International Space Station'), t('Xedfild 2001-yilda uni yig‘ishda qatnashgan, 2013-yilda esa unga qo‘mondonlik qilgan.','Хэдфилд участвовал в её сборке в 2001 году и командовал ею в 2013 году.','Hadfield helped assemble it in 2001 and commanded it in 2013.'), null]
