    [t('«Crew Dragon» kemasi','Корабль Crew Dragon','Crew Dragon spacecraft'), t('SpaceX kompaniyasining qayta foydalaniladigan kemasi; 2022-yilgi «Minerva» missiyasi uchun ishlatilgan.','Многоразовый корабль компании SpaceX, использованный в миссии «Минерва» 2022 года.','SpaceX’s reusable spacecraft, used for the 2022 Minerva mission.'), null],
    [t('Xalqaro kosmik stansiya','Международная космическая станция','International Space Station'), t('Ikki missiyada jami bir yildan ortiq yashagan va unga qo‘mondonlik qilgan joyi.','Место, где она в двух миссиях прожила больше года и которым командовала.','Where she lived for over a year across two missions and which she commanded.'), null]
