    [2015, t('199 kunlik parvozdan qaytdi — ayollar rekordi','Вернулась из 199-суточного полёта — женский рекорд','Returned from a 199-day flight — a women’s record')],
    [2022, t('«Minerva»: ochiq kosmosga chiqdi va 68-ekspeditsiya komandiri bo‘ldi','«Минерва»: выход в открытый космос и командование 68-й экспедицией','Minerva: spacewalk and command of Expedition 68')]
